-- FASHORA minimal seed: users + wardrobe_items (embedding NULL, no history).
-- Run after backend starts once. All logins use password: FashoraDev123!
BEGIN;
SELECT setval(pg_get_serial_sequence('users','id'), COALESCE((SELECT MAX(id) FROM users),1));
SELECT setval(pg_get_serial_sequence('wardrobe_items','id'), COALESCE((SELECT MAX(id) FROM wardrobe_items),1));
COMMIT;
